/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg a = 0;
  wire match;

  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));

  always #5 clk = ~clk;

  task send_bit(input reg bitval);
    begin
      a = bitval;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b shift=%09b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    $display("start");
    repeat (2) @(posedge clk);
    rst_n = 1;

    // Pattern 011000110 should match
    send_bit(0); send_bit(1); send_bit(1); send_bit(0); send_bit(0); send_bit(0); send_bit(1); send_bit(1); send_bit(0);

    // extra cycles
    send_bit(0); send_bit(0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

